25	/**
26	 * Resolve an install target, expanding the conventional ~/ prefix. The result
27	 * is always absolute.
28	 *
29	 * Notes:
30	 * - Installing to an arbitrary absolute path (including `..`-relative ones
31	 *   that resolve outside cwd) is intentionally allowed; users routinely ask
32	 *   pisquad to install into a sibling directory (e.g. `pisquad install ../foo`).
33	 * - Inputs that look like a typo for `~` but aren't (e.g. `~bob/proj`,
34	 *   `~user/...`) are NOT shell-expanded — they would silently land in
35	 *   `./cwd/~bob/proj` instead of bob's home. We log a heads-up so the user can
36	 *   notice the path is unexpected.
37	 * - Callers (notably `installCommand`) print the resolved absolute path so
38	 *   the user always sees the real install destination.
39	 */
40	export function resolveTarget(input?: string, cwd = process.cwd()): string {
41	  const value = input ?? cwd;
42	  let expanded: string;
43	  if (value === "~") {
44	    expanded = homedir();
45	  } else if (value.startsWith("~/")) {
46	    expanded = join(homedir(), value.slice(2));
47	  } else if (value.startsWith("~")) {
48	    // Looks like a tilde-prefix that we do NOT expand (e.g. "~user/proj").
49	    // Avoid silent relative-path resolution — warn so the user can react.
50	    console.warn(`pisquad: target "${value}" starts with "~" but is not "~" or "~/" — leaving it for the shell to expand. Did you mean "~/${value.slice(1)}"?`);
51	    expanded = value;
52	  } else {
53	    expanded = value;
54	  }
55	  return resolve(cwd, expanded);
56	}
57	
58	/** Return the state file belonging to an install target. */
